/** Tuple queries that ask for the result cache are answered from it until the store's next write. */
class LmdbQueryResultCacheTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:result-cache:";
	private static final IRI PERSON = VF.createIRI(NS, "Person");
	private static final IRI PLACE = VF.createIRI(NS, "Place");
	private static final IRI GRAPH = VF.createIRI(NS, "g");
	private static final String TYPE_COUNTS = "SELECT ?type (COUNT(DISTINCT ?s) AS ?instances) "
			+ "WHERE { ?s a ?type } GROUP BY ?type ORDER BY ?type";

	@TempDir
	File directory;

	private SailRepository repository;
	private LmdbStore store;

	@BeforeEach
	void setUp() {
		store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc"));
		repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int i = 0; i < 10; i++) {
				connection.add(VF.createIRI(NS, "p" + i), RDF.TYPE, PERSON);
			}
			connection.add(VF.createIRI(NS, "oslo"), RDF.TYPE, PLACE, GRAPH);
			connection.commit();
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void aSecondHintedEvaluationIsServedFromTheCache() {
		List<String> first = evaluate(TYPE_COUNTS, true);
		List<String> second = evaluate(TYPE_COUNTS, true);

		assertThat(first).containsExactly(NS + "Person=10", NS + "Place=1");
		assertThat(second).isEqualTo(first);
		assertThat(stats().stores()).isEqualTo(1);
		assertThat(stats().hits()).isEqualTo(1);
	}

	@Test
	void queryScopedNowIsNotCachedAcrossExecutions() {
		String query = "SELECT (NOW() AS ?now) WHERE { ?s ?p ?o } LIMIT 1";
		List<Value> first = values(query, "now");
		List<Value> second = values(query, "now");

		assertThat(first).hasSize(1);
		assertThat(second).hasSize(1);
		assertThat(stats().stores()).as("NOW is scoped to one query execution").isZero();
		assertThat(stats().hits()).as("NOW is scoped to one query execution").isZero();
	}

	@Test
	void everyKindOfCommittedWriteInvalidatesTheEntry() {
		evaluate(TYPE_COUNTS, true);

		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createIRI(NS, "p10"), RDF.TYPE, PERSON);
		}
		assertThat(evaluate(TYPE_COUNTS, true)).containsExactly(NS + "Person=11", NS + "Place=1");

		try (RepositoryConnection connection = repository.getConnection()) {
			connection.remove(VF.createIRI(NS, "oslo"), null, null);
		}
		assertThat(evaluate(TYPE_COUNTS, true)).containsExactly(NS + "Person=11");

		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			connection.add(VF.createIRI(NS, "bergen"), RDF.TYPE, PLACE);
			connection.commit();
		}
		assertThat(evaluate(TYPE_COUNTS, true)).containsExactly(NS + "Person=11", NS + "Place=1");

		try (RepositoryConnection connection = repository.getConnection()) {
			connection.clear();
		}
		assertThat(evaluate(TYPE_COUNTS, true)).isEmpty();
		assertThat(stats().hits()).isZero();
	}

	@Test
	void queriesThatDoNotAskForTheCacheNeverUseIt() {
		evaluate(TYPE_COUNTS, false);
		evaluate(TYPE_COUNTS, false);

		assertThat(stats().stores()).isZero();
		assertThat(stats().hits()).isZero();
	}

	@Test
	void aResultReadOnlyInPartIsNotCached() {
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = hinted(connection, TYPE_COUNTS).evaluate()) {
			assertThat(result.hasNext()).isTrue();
			result.next();
		}

		assertThat(stats().stores()).isZero();
	}

	@Test
	void queriesInsideATransactionSeeTheirOwnChangesAndAreNotCached() {
		evaluate(TYPE_COUNTS, true);
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			connection.add(VF.createIRI(NS, "p10"), RDF.TYPE, PERSON);
			assertThat(rows(hinted(connection, TYPE_COUNTS))).containsExactly(NS + "Person=11", NS + "Place=1");
			connection.rollback();
		}

		assertThat(stats().stores()).isEqualTo(1);
		assertThat(stats().hits()).isZero();
	}

	@Test
	void bindingsAndDatasetsAreDifferentQueries() {
		String instances = "SELECT ?s WHERE { ?s a ?type } ORDER BY ?s";
		try (RepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery places = hinted(connection, instances);
			places.setBinding("type", PLACE);
			assertThat(rows(places)).containsExactly(NS + "oslo");
			SailTupleQuery people = hinted(connection, instances);
			people.setBinding("type", PERSON);
			assertThat(rows(people)).hasSize(10);
			SailTupleQuery inGraph = hinted(connection, instances);
			SimpleDataset dataset = new SimpleDataset();
			dataset.addDefaultGraph(GRAPH);
			inGraph.setDataset(dataset);
			assertThat(rows(inGraph)).containsExactly(NS + "oslo");
			places = hinted(connection, instances);
			places.setBinding("type", PLACE);
			assertThat(rows(places)).containsExactly(NS + "oslo");
		}

		assertThat(stats().stores()).isEqualTo(3);
		assertThat(stats().hits()).isEqualTo(1);
	}

	@Test
	void cachedBlankNodesStillIdentifyTheStoredNodes() {
		BNode blank = VF.createBNode("cached-blank");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(blank, RDF.TYPE, PLACE);
		}
		String blanks = "SELECT ?s WHERE { ?s a <" + PLACE + "> FILTER(isBlank(?s)) }";
		List<Value> first = values(blanks, "s");
		List<Value> cached = values(blanks, "s");

		assertThat(stats().hits()).isEqualTo(1);
		assertThat(cached).hasSize(1).isEqualTo(first);
		try (RepositoryConnection connection = repository.getConnection()) {
			assertThat(connection.hasStatement((BNode) cached.get(0), RDF.TYPE, PLACE, true)).isTrue();
		}
	}

	@Test
	void entriesStayWithinTheirRowLimits() {
		LmdbQueryResultCache cache = new LmdbQueryResultCache(3, 5);
		LmdbQueryResultCache.Key small = key("small");
		LmdbQueryResultCache.Key large = key("large");
		LmdbQueryResultCache.Key other = key("other");

		drain(cache.record(large, 1, () -> 1, rows(4)));
		drain(cache.record(small, 1, () -> 1, rows(3)));
		drain(cache.record(other, 1, () -> 1, rows(3)));
		drain(cache.record(key("changed"), 1, () -> 2, rows(1)));

		assertThat(cache.lookup(large, 1)).as("larger than one entry may be").isEmpty();
		assertThat(cache.lookup(small, 1)).as("evicted to make room").isEmpty();
		assertThat(cache.lookup(other, 1)).isPresent();
		assertThat(cache.lookup(key("changed"), 1)).as("revision changed while it was read").isEmpty();
		assertThat(cache.lookup(other, 2)).as("a later revision").isEmpty();
		assertThat(cache.stats().rows()).isZero();
	}

	private static LmdbQueryResultCache.Key key(String name) {
		return new LmdbQueryResultCache.Key(name, Map.of(), null, null, false, true);
	}

	private static CloseableIteration<BindingSet> rows(int count) {
		List<BindingSet> rows = new ArrayList<>();
		IntStream.range(0, count).forEach(i -> {
			MapBindingSet row = new MapBindingSet();
			row.addBinding("i", VF.createLiteral(i));
			rows.add(row);
		});
		return new CloseableIteratorIteration<>(rows.iterator());
	}

	private static void drain(CloseableIteration<BindingSet> iteration) {
		try (iteration) {
			while (iteration.hasNext()) {
				iteration.next();
			}
		}
	}

	private LmdbQueryResultCache.Stats stats() {
		return store.getBackingStore().queryResultCache().stats();
	}

	private List<String> evaluate(String query, boolean cached) {
		try (RepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery tupleQuery = (SailTupleQuery) connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
			tupleQuery.setLmdbResultCacheRequested(cached);
			return rows(tupleQuery);
		}
	}

	private List<Value> values(String query, String name) {
		List<Value> values = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = hinted(connection, query).evaluate()) {
			result.forEach(row -> values.add(row.getValue(name)));
		}
		return values;
	}

	private static SailTupleQuery hinted(RepositoryConnection connection, String query) {
		SailTupleQuery tupleQuery = (SailTupleQuery) connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
		tupleQuery.setLmdbResultCacheRequested(true);
		return tupleQuery;
	}

	private static List<String> rows(SailTupleQuery query) {
		List<String> rows = new ArrayList<>();
		try (TupleQueryResult result = query.evaluate()) {
			for (BindingSet row : result) {
				Value type = row.getValue("type");
				Value count = row.getValue("instances");
				rows.add(type == null ? row.getValue("s").stringValue()
						: type.stringValue() + "=" + count.stringValue());
			}
		}
		return rows;
	}
}
